//@ts-ignore
import {$CombinedState} from '@reduxjs/toolkit';
import {LitElement} from 'lit';
import {connect} from 'pwa-helpers/connect-mixin';

import {reduxStore} from '../../space_opera_base.js';

// This is only here because we can't export this directly.
const connectedLitElementInternal = connect(reduxStore)(LitElement);

/**
 * Extending this class means your element will have its "stateChanged" method
 * invoked any time SpaceOpera's Redux store is changed.
 */
export class ConnectedLitElement extends connectedLitElementInternal {
  get storeState() {
    return reduxStore.getState();
  }
}
